      <nav class="tabs"><button class="tab" data-tab="cart">${t7("清单", "Cart")}</button><button class="tab" data-tab="plans">${t7("计划", "Plans")}</button><button class="tab" data-tab="settings">${t7("设置", "Settings")}</button></nav>
